": "concept", "title": "Nineveh"}, {"id": "f0717b58-f8aa-4eb3-8455-c269510cc963", "type": "concept", "title": "deportation"}, {"id": "98ac3e3f-386d-40ab-a092-4fbbdb02eae4", "type": "concept", "title": "tribute"}, {"id": "44417e20-84a7-49ca-843a-876883a0a6f0", "type": "concept", "title": "military logistics"}, {"id": "420d4b88-a42b-481e-9447-427c0c2497f6", "type": "concept", "title": "provincial administration"}, {"id": "92918225-fccc-4205-bbe7-2a8a4bf884b4", "type": "concept", "title": "palace reliefs"}, {"id": "38284a79-109f-413d-8c49-93c0453c1086", "type": "concept", "title": "Ashurbanipal"}], "description": "This subtopic shows the mechanisms and costs of territorial empire."}]}, {"id": "7a7afa30-d6c3-4123-9831-a254ec0b7c02", "type": "topic", "title": "Ancient Egypt: Nile Ecology, Kingship, Religion, and Society", "description": "This topic treats Egypt as a long-lived civilization whose environment, institutions, belief systems, and monuments must be studied together. Students learn to connect ecology, ideology, material culture, and social organization.", "children": [{"id": "ec76dad5-220e-48e3-be55-e4280585dcb3", "type": "subtopic", "title": "Nile ecology and state formation", "children": [{"id": "c1488fea-7650-4f21-9a14-070091592a4d", "type": "concept", "title": "inundation"}, {"id": "5d9cfa91-2aa1-42e3-a7ab-cdf1623bd1e8", "type": "concept", "title": "floodplain agriculture"}, {"id": "4c94eab3-002e-42c4-9b8a-4f470529bf88", "type": "concept", "title": "Upper Egypt"}, {"id": "51e086bf-3a2f-46e6-af80-60dedc8133cd", "type": "concept", "title": "Lower Egypt"}, {"id": "9e00963a-8d32-4012-823b-a1e3aa5c9093", "type": "concept", "title": "Memphis"}, {"id": "bd1ed3a2-8261-4026-82c9-9015fe2ce5aa", "type": "concept", "title": "nome"}, {"id": "1afef5a1-af2b-4a71-9188-38e55b631e85", "type": "concept", "title": "granaries"}, {"id": "bbcd259a-9577-43fc-81e8-724c7e90f7f0", "type": "concept", "title": "centralization"}], "description": "Students learn how the Nile shaped agriculture, transport, taxation, and political integration."}, {"id": "33aee246-4874-4d15-8fef-8d98c8355db3", "type": "subtopic", "title": "Pharaoh, gods, and cosmic order", "children": [{"id": "07554acd-2a15-4404-ad12-f548cc1b6326", "type": "concept", "title": "pharaoh"}, {"id": "516bd966-3a7b-4589-bce7-6d02f461c928", "type": "concept", "title": "ma'at"}, {"id": "d8878ad3-2894-4b6d-a1a6-f2a738942fc6", "type": "concept", "title": "Osiris"}, {"id": "a4d7fb9e-fe7c-4bea-955a-0b61a009831d", "type": "concept", "title": "Isis"}, {"id": "0caea65b-f8be-4ead-8a30-80832c4793c9", "type": "concept", "title": "Ra"}, {"id": "a0b5b53d-d36e-46b6-8e67-819ac365f713", "type": "concept", "title": "Amun"}, {"id": "9a699c1b-6278-458d-89ed-899894ebc218", "type": "concept", "title": "divine kingship"}, {"id": "21d193fe-6c13-45bf-bf29-f0fd7327fe5d", "type": "concept", "title": "temple ritual"}, {"id": "e65492c6-bb41-4a66-871e-8a1387a5c42a", "type": "concept", "title": "afterlife"}], "description": "This subtopic explains kingship as political, religious, and symbolic power."}, {"id": "cc59c4e5-0548-41f4-a9ce-c27a0da13f9d", "type": "subtopic", "title": "Monuments, labor, and daily life", "children": [{"id": "f63b5cd4-65ae-4e22-8eac-59f82c840340", "type": "concept", "title": "pyramids"}, {"id": "d5e8145a-7f54-44c7-8e10-1572e681e64c", "type": "concept", "title": "mastaba"}, {"id": "5ecb0a95-5865-4032-8ae3-132db0258a62", "type": "concept", "title": "tomb painting"}, {"id": "a72c3eb8-51f7-4f67-ae07-1e96653a382e", "type": "concept", "title": "Deir el-Medina"}, {"id": "9931672c-8a14-4c8f-a9f8-50533c196382", "type": "concept", "title": "corvee labor"}, {"id": "e331f946-ab43-4aeb-a555-84b4a66de4ba", "type": "concept", "title": "scribal culture"}, {"id": "642ec170-c0c2-4cc8-bc0e-42b52e230d17", "type": "concept", "title": "households"}, {"id": "cf948778-b567-420e-8cfa-955cae4d94d1", "type": "concept", "title": "gender roles"}], "description": "Students read monuments as social evidence, not just spectacle."}]}, {"id": "2a3188db-118d-4106-a071-829160cde0de", "type": "topic", "title": "Bronze Age Networks, Collapse, and the Eastern Mediterranean", "description": "This unit examines the interconnected Bronze Age world and the causes and consequences of its disruption around 1200 BCE. Students analyze trade, diplomacy, warfare, climate, migration, and systems collapse.", "children": [{"id": "5ca8d2dc-e6d1-461a-8389-998f33be5e82", "type": "subtopic", "title": "Diplomacy and exchange", "children": [{"id": "c67b9c75-70a0-4d0a-b5a3-79c438c3edbc", "type": "concept", "title": "Amarna letters"}, {"id": "34c98653-81ae-403b-bcb4-1b63dac6cd45", "type": "concept", "title": "diplomatic marriage"}, {"id": "09fa580f-ab05-4ad5-b945-ec640ee9b4ec", "type": "concept", "title": "gift exchange"}, {"id": "85251a4b-4c96-44be-9542-9dde30efdb89", "type": "concept", "title": "tin trade"}, {"id": "9a95660e-3303-4e58-a1aa-f9a388216992", "type": "concept", "title": "copper"}, {"id": "5160ac7a-0605-4886-88a7-87049ff4ea72", "type": "concept", "title": "Ugarit"}, {"id": "f424812f-bc38-4ec5-9720-98cd1159fd58", "type": "concept", "title": "Cyprus"}, {"id": "644c07ab-804d-40a7-8328-075a04cf50b6", "type": "concept", "title": "palatial economies"}], "description": "Students learn that Bronze Age polities were connected through gifts, marriage, trade, and correspondence."}, {"id": "9bd00be8-b047-4c2e-accd-9e6530e3c19e", "type": "subtopic", "title": "Anatolia, the Levant, and Aegean worlds", "children": [{"id": "b52dfbe9-e6fa-489b-a913-7989c7a89bb3", "type": "concept", "title": "Hittites"}, {"id": "f0c9bac4-1aac-4ad0-ba19-e77cd6498c29", "type": "concept", "title": "Mycenaeans"}, {"id": "6479b401-34c0-435c-90b5-c94860fcfe74", "type": "concept", "title": "Minoans"}, {"id": "919e2af7-c276-4963-9478-04c26745d2c4", "type": "concept", "title": "Knossos"}, {"id": "cb75092c-6f09-48cf-b6ea-66cc5b797bc8", "type": "concept", "title": "Hattusa"}, {"id": "96a2c03f-249a-4538-a31a-3d6b513dc2cb", "type": "concept", "title": "Levantine ports"}, {"id": "136c27c2-46a2-446a-980a-b6b2a19c5b87", "type": "concept", "title": "Linear B"}, {"id": "c1e4ef50-bae3-41eb-8a9e-ef1ed56074af", "type": "concept", "title": "chariot warfare"}], "description": "This subtopic broadens the field beyond Egypt and Mesopotamia."}, {"id": "7a82fe27-1992-429d-b00f-01ee3f4a49de", "type": "subtopic", "title": "Bronze Age collapse", "children": [{"id": "19841f78-359e-47cf-a869-c95fe6c32de8", "type": "concept", "title": "Sea Peoples"}, {"id": "a8701076-c2c9-4c51-bb71-c9be7e91e5e2", "type": "concept", "title": "climate stress"}, {"id": "e8768150-0f31-4b22-99f1-2b8ce50076c2", "type": "concept", "title": "earthquakes"}, {"id": "de083ecb-f80b-4485-9ebe-066b0deecbcd", "type": "concept", "title": "systems collapse"}, {"id": "ac6fef81-6d41-42a4-bdc4-cb35c1a3de30", "type": "concept", "title": "migration"}, {"id": "8d1d48fc-4753-451b-a7ab-18493ed42c34", "type": "concept", "title": "trade disruption"}, {"id": "96d523f2-f703-4238-9a54-2416757dfc7a", "type": "concept", "title": "palace destruction"}, {"id": "99d5d225-2850-4378-84b8-69bc81ecf8e2", "type": "concept", "title": "continuity and transformation"}], "description": "Students compare mono-causal and multi-causal explanations for historical breakdown."}]}, {"id": "1e549a39-1e1a-4a2d-8a2b-cd0d65452bfd", "type": "topic", "title": "Iron Age States, Israel, Phoenicia, and the Achaemenid Persian Empire", "description": "This topic follows new political and cultural formations after the Bronze Age and culminates in the first major empire spanning much of the Near East. Students learn how smaller kingdoms, maritime networks, and imperial systems remade the ancient world.", "children": [{"id": "a3ee796d-398e-4a2d-9317-046f947fd78e", "type": "subtopic", "title": "Iron Age kingdoms and identities", "children": [{"id": "1f6d885e-00db-47cc-85a5-8a78e6438032", "type": "concept", "title": "Israel"}, {"id": "5c769d2d-5fa1-41fc-9e81-462b5f4910c7", "type": "concept", "title": "Judah"}, {"