e8-8646-4436-9a15-75d53fff757f", "type": "concept", "title": "Royal Road"}, {"id": "35a463ea-e5da-4188-a5dc-b9b1f1235224", "type": "concept", "title": "tribute"}, {"id": "5be78710-235a-43c6-9daa-3d4c3a1296af", "type": "concept", "title": "Persepolis"}, {"id": "8bd6b5c2-a1f9-4751-8584-57ac184be58e", "type": "concept", "title": "imperial Aramaic"}, {"id": "2020722a-b83e-4a07-9c19-0d9216b9360a", "type": "concept", "title": "Zoroastrian traditions"}], "description": "Students learn why Persian imperial administration is central to Greek, Near Eastern, and global ancient history."}]}, {"id": "94ab38a7-ddd8-44ed-9927-7ce85f08bc3e", "type": "topic", "title": "Archaic Greece: Polis Formation, Colonization, and Social Change", "description": "This unit explains the rise of the Greek polis and the social tensions that shaped law, citizenship, and political experimentation. Students learn how local communities, colonization, and class conflict produced durable institutions.", "children": [{"id": "261c1cdf-8665-4e1e-b4ed-9732c9992131", "type": "subtopic", "title": "The polis and civic identity", "children": [{"id": "60d151e4-4610-44b4-a326-fbaeb5500e0f", "type": "concept", "title": "polis"}, {"id": "9bae0f0a-05a4-4ff3-8f67-7f0b6d7f1b8d", "type": "concept", "title": "acropolis"}, {"id": "79a8efc0-438e-4b43-883f-ba6f9d8830da", "type": "concept", "title": "agora"}, {"id": "83388427-af1a-4c55-95d1-2316ac080522", "type": "concept", "title": "citizenship"}, {"id": "eb6a5046-c222-47c3-90e2-6011a0751555", "type": "concept", "title": "hoplite"}, {"id": "7742e3c7-a897-445d-a757-dadb700dce5d", "type": "concept", "title": "phratry"}, {"id": "d62d2544-bd6e-488e-a002-bb6c0aee4041", "type": "concept", "title": "civic cult"}, {"id": "88ff5eb6-6299-4ed5-b5ba-1bcb2d0b8919", "type": "concept", "title": "oikos"}], "description": "Students understand the polis as community, territory, institutions, cult, and identity."}, {"id": "dbb5ab2e-520e-4f34-ad82-9e05c850cd5d", "type": "subtopic", "title": "Colonization and mobility", "children": [{"id": "d34f646e-b5c6-46cb-b98e-fd9300c8ffc8", "type": "concept", "title": "apoikia"}, {"id": "eb1f19f9-6c0a-49c1-ab16-339a5a03fc24", "type": "concept", "title": "metropole"}, {"id": "1ea86ef4-7c9f-4640-a926-90ac6722d8ae", "type": "concept", "title": "Magna Graecia"}, {"id": "a1032394-1dcc-419f-a922-beb861105eda", "type": "concept", "title": "Black Sea colonies"}, {"id": "fda247dc-b03e-4c15-8a58-504d9d525a4a", "type": "concept", "title": "trade"}, {"id": "61cb1a30-08cc-448e-a1eb-e83bf1337202", "type": "concept", "title": "land hunger"}, {"id": "c8a98c57-dded-4248-a69c-24abc327409b", "type": "concept", "title": "cultural exchange"}, {"id": "9a7c19f2-f7f9-4a84-8ef6-e5f583e9b33b", "type": "concept", "title": "colonial violence"}], "description": "This subtopic looks at Greek settlements as economic, demographic, and cultural expansion."}, {"id": "a4ab32f4-ea89-406c-a540-7f6fc7400892", "type": "subtopic", "title": "Lawgivers, tyrants, and social reform", "children": [{"id": "db3534d6-11b1-467f-b401-e522fde79ae1", "type": "concept", "title": "Draco"}, {"id": "4cd79993-8812-466c-9dac-85dfe82a39b2", "type": "concept", "title": "Solon"}, {"id": "45c11e8d-6990-4a21-88f9-599346384004", "type": "concept", "title": "tyranny"}, {"id": "4fdc35dc-fe6f-49af-9bdf-5fce52b16524", "type": "concept", "title": "stasis"}, {"id": "f9f4b02f-3513-4bb2-83c2-d41fdf622ecd", "type": "concept", "title": "debt bondage"}, {"id": "05382cb4-869e-4bda-bb3b-2f13f351d15a", "type": "concept", "title": "aristocracy"}, {"id": "e004056a-2bcc-45c5-9d39-2d8efb67ea52", "type": "concept", "title": "symposium"}, {"id": "802dd82c-e95d-4469-a31f-05dd99f42ed4", "type": "concept", "title": "written law"}], "description": "Students connect political change to debt, aristocracy, and popular pressure."}]}, {"id": "20ca5178-6920-4c44-b4d6-b1a7f83b4edc", "type": "topic", "title": "Classical Greece: Democracy, Empire, War, and Culture", "description": "This topic examines the Classical Greek world through Athens, Sparta, Persian conflict, imperial power, and cultural production. Students analyze democracy, militarization, empire, drama, philosophy, and historical writing together.", "children": [{"id": "29b40d34-1c59-4431-a5aa-d818260e7fcb", "type": "subtopic", "title": "Athens and democracy", "children": [{"id": "38e7e0c7-e77f-4563-8933-30b3ba1345c0", "type": "concept", "title": "ekklesia"}, {"id": "7c9abc93-1555-48d2-9ab3-67b7597d88f5", "type": "concept", "title": "boule"}, {"id": "3dcb94f5-cf55-4293-9c56-acae25fc2bed", "type": "concept", "title": "dikasteria"}, {"id": "8104fd40-1558-47f2-828b-c3aab9b8def8", "type": "concept", "title": "ostracism"}, {"id": "bb894fe3-9273-4724-b395-87b3f342b3be", "type": "concept", "title": "liturgies"}, {"id": "90040217-c834-45e8-b481-966414b11a66", "type": "concept", "title": "metoikoi"}, {"id": "33412643-f2d1-45c3-8d47-1b8f94df8f84", "type": "concept", "title": "slavery"}, {"id": "452b525d-bcbf-465d-9075-f5b7c4efa15c", "type": "concept", "title": "Pericles"}], "description": "Students learn the institutions and exclusions of direct democracy."}, {"id": "0d34cff7-ebe5-4002-9faf-b1d5e54918bc", "type": "subtopic", "title": "Sparta, Persia, and war", "children": [{"id": "6b2a94ac-f627-46dc-98c8-7e5660fb7854", "type": "concept", "title": "Sparta"}, {"id": "c0113e76-d739-4b2f-ae07-60822a325f07", "type": "concept", "title": "helots"}, {"id": "b229b4cc-ec42-4462-9603-b0cf557f37bb", "type": "concept", "title": "agoge"}, {"id": "ead34dd9-89c5-4292-8e1a-b96d013951ef", "type": "concept", "title": "Persian Wars"}, {"id": "04e4915d-b79c-4c54-bba6-3b56f6e99ec0", "type": "concept", "title": "Marathon"}, {"id": "54f16c61-88b9-48ea-be0a-278f69b17255", "type": "concept", "title": "Thermopylae"}, {"id": "489512bf-8103-41e3-8eef-23d848d38578", "type": "concept", "title": "Delian League"}, {"id": "8c7e90d1-cda6-4a3c-a0fb-23194841a7dc", "type": "concept", "title": "Peloponnesian War"}], "description": "This subtopic compares military cultures and interstate conflict."}, {"id": "5317a307-85be-490e-85b7-4b534be4c4ec", "type": "subtopic", "title": "Culture and historical memory", "children": [{"id": "5d8579d0-7bed-4edb-ada5-7dec9f057335", "type": "concept", "title": "tragedy"}, {"id": "35af286f-5000-4a39-a7ce-9c2eb69f5df0", "type": "concept", "title": "comedy"}, {"id": "b4cf32db-2416-4c35-a985-d45286b894e4", "type": "concept", "title": "Herodotus"}, {"id": "947af4b3-f7a1-43c8-a7b6-d626ea53aa5e", "type": "concept", "title": "Thucydides"}, {"id": "ec2ad166-2222-474b-be60-cd57db0c0a72", "type": "concept", "title": "Socrates"}, {"id": "489dfd73-1441-4f6d-865b-0a7462c89e95", "type": "concept", "title": "Sophists"}, {"id": "94033931-b06c-47dc-bed0-d8448c6d8cc4", "type": "concept", "title": "Parthenon"}, {"id": "1ede6029-a88b-4ba4-8917-60f353a64434", "type": "concept", "title": "Panhellenism"}], "description": "Students read cultural works as evidence for values, conflict, and civic debate."}]}, {"id": "10eca40d-3e87-43d9-9a5d-212317d48e56", "type": "topic", "title": "The Hellenistic World: Alexander, Kingdoms, Cities, and Cultural Exchange", "description": "This unit follows the world created by Macedonian conquest, successor kingdoms, new cities, and cross-cultural exchange from Egypt to Central Asia. Students understand Hellenistic history as both imperial and hybrid.", "children": [{"id": "e803d12f-2efb-4112-a89b-7c00ae2d893e", "type": "subtopic", "title": "Alexander and conquest", "children": [{"id": "1980b367-7ca6-4558-b95a-26edcb0713d0", "type": "concept", "title": "Macedon"}, {"id": "2fac9fc5-7fff-4787-af53-5f2c22c5345c", "type": "concept", "title": "Philip II"}, {"id": "2fc7b735-7bc5-44ef-811b-5884ee8ae330", "type": "concept", "title": "Alexander"}, {"id": "6854b3b4-001d-4a06-94ec-0b5f1664fa7e", "type": "concept", "title": "Granicus"}, {"id": "3607583f-a6a0-4607-89e4-606db51ba023", "type": "concept", "title": "Issus"}, {"id": "080919a5-0db5-4790-804d-e7010991703e", "type": "concept", "title": "Gaugamela"}, {"id": "562a32b0-8363-4e57-a374-a0ee0dc60641", "type": "concept", "title": "siege warfare"}, {"id": "17ae48d5-ce5b-45ae-a292-1e28ef3b1495", "type": "concept", "title": "charismatic kingship"}], "description": "Students examine how rapid conquest transformed political geography and historical memory."}, {"id": "35cc5bec-fe28-4abe-a343-577e4c826685", "type": "subtopic", "title": "Successor kingdoms and cities", "children": [{"id": "ecf57209-af2e-416b-a699-6fa56f283680", "type": "concept", "title": "Diadochi"}, {"id": "0f913d28-f4c7-4670-bcfa-f1923b8b475e", "type": "concept", "title": "Ptolemies"}, {"id": "968c7d44-ec04-4549-8a92-152c2c93c4fb", "type": "concept", "title": "Seleucids"}, {"id": "c52f5823-686c-499b-9550-4cbcc9558403", "type": "concept", "title": "Antigonids"}, {"id": "1e91c11b-d40a-48e1-9202-2884a869f22f", "type": "concept", "title": "Alexandria"}, {"id": "e353e6ed-40cd-4f07-b382-b70aa1579332", "type": "concept", "title": "Pergamon"}, {"id": "4ba64819-65b0-4821-a08b-7d5420f37bdf", "type": "concept", "title": "polis autonomy"}, {"id": "e76b261d-c67f-4f8a-a333-f589d037bfca", "type": "concept", "title": "royal patronage"}], "description": "This subtopic studies new monarchies and urban centers as engines of administration and culture."}, {"id": "147eec0c-97c7-4feb-958a-93a0ea103cb8", "type": "subtopic", "title": "Cultural exchange and knowledge", "children": [{"id": "b11a9016-e7ac-489b-b818-dc10b7030623", "type": "concept", "title": "koine Greek"}, {"id": "a611c06f-2bd5-4e8f-96bb-f842612842b8", "type": "concept", "title": "syncretism"}, {"id": "d6598d8b-6565-45b6-a222-93965cc2d390", "type": "concept", "title": "Library of Alexandria"}, {"id": "a643830b-7bfc-49ed-a9d7-a58dee106c84", "type": "concept", "title": "mystery cults"}, {"id": "82552f1c-f4dc-4322-9494-a9d62a8e90b5", "type": "concept", "title": "Jews in diaspora"}, {"id": "c6102581-2442-4952-bf69-8e04a6f69172", "type": "concept", "title": "Greco-Bactria"}, {"id": "72b79a2a-7b41-4a6f-ac