ic scope"}, {"id": "b2a0336c-4420-4f54-8def-e6dc61072139", "type": "concept", "title": "research question"}, {"id": "acf58073-52c1-4c9e-b039-835954408a49", "type": "concept", "title": "primary evidence"}, {"id": "7934841e-2758-4d7b-86d0-69932788c5ad", "type": "concept", "title": "secondary literature"}, {"id": "d6a62145-fb4e-4474-8463-7f9ac040e6ea", "type": "concept", "title": "historiographical debate"}, {"id": "d9702a25-2cfe-4c4b-8817-18c8c3e9ae96", "type": "concept", "title": "feasibility"}, {"id": "ff2f7114-843b-466f-a318-02bd365b42da", "type": "concept", "title": "working bibliography"}], "description": "Students learn to narrow a broad ancient topic into a source-driven historical problem."}, {"id": "540eb616-aaaf-4ed3-beae-bf58789ce17a", "type": "subtopic", "title": "Building the argument", "children": [{"id": "997a7849-8b48-4ed9-af46-4ae18aa77da5", "type": "concept", "title": "thesis"}, {"id": "7ebffaf8-fa43-4985-9abd-193e649fab02", "type": "concept", "title": "source analysis"}, {"id": "93feee1e-df02-4353-8fe1-1a2ec4b2c7fa", "type": "concept", "title": "counterargument"}, {"id": "a6836a73-c7e3-461e-b9cc-fe12304da570", "type": "concept", "title": "comparative evidence"}, {"id": "be70a7ed-08e8-49d2-b355-21d44d5b3419", "type": "concept", "title": "chronological structure"}, {"id": "3a45e4ae-8f17-440d-9f80-77ccaf09e472", "type": "concept", "title": "causal claim"}, {"id": "86e49edf-6f16-40c2-9397-57b6df686002", "type": "concept", "title": "interpretive stakes"}], "description": "This subtopic guides students from evidence collection to analytical structure."}, {"id": "96355732-505c-450f-8638-c1e739f72a7f", "type": "subtopic", "title": "Writing, citation, and presentation", "children": [{"id": "5c9da722-5587-4f52-a8a5-9d208ec8f166", "type": "concept", "title": "Chicago style"}, {"id": "8dae4656-fd43-47b7-80c5-b3202696fb02", "type": "concept", "title": "footnotes"}, {"id": "c3d682da-0223-4bcd-8a26-0c2f8b091515", "type": "concept", "title": "bibliography"}, {"id":