  data = $anchjson${"slug": "ancient-history", "title": "Ancient History", "description": "The syllabus moves from evidence and early state formation through Mesopotamia, Egypt, Bronze Age networks, Persia, Greece, the Hellenistic world, Rome, social and religious history, late antiquity, historiography, archaeology, reception, and a final research project.", "topics": [{"id": "09a6488d-1d8f-4dc0-a462-d811efa0a492", "type": "topic", "title": "Ancient History as a Field: Chronology, Geography, and Evidence", "description": "This opening topic teaches students how ancient historians build knowledge from fragmentary evidence across vast chronological and regional scope. Students learn to map major ancient regions, periodize responsibly, and distinguish source types.", "children": [{"id": "f75519f3-255e-43bc-8368-3e091081aa06", "type": "subtopic", "title": "Periodization and geography", "children": [{"id": "d6468cb3-e9df-41fc-9ba5-e66c4ac3986d", "type": "concept", "title": "Neolithic"}, {"id": "225789b1-547d-4730-add1-78fd1cee6759", "type": "concept", "title": "Bronze Age"}, {"id": "ae7e1705-2650-406b-b670-a80030fddc10", "type": "concept", "title": "Iron Age"}, {"id": "3fff1a72-bd56-4034-86b5-953fe04303e4", "type": "concept", "title": "Classical period"}, {"id": "fc7f81cd-038d-4b96-9879-1750c0d4d527", "type": "concept", "title": "Hellenistic period"}, {"id": "118fafff-cf92-431a-885e-378cf8b66e59", "type": "concept", "title": "Roman Republic"}, {"id": "cb242a8a-d689-4439-b8af-96689daa0654", "type": "concept", "title": "Roman Empire"}, {"id": "165c031b-8c03-4bc9-acc2-34604320e164", "type": "concept", "title": "late antiquity"}, {"id": "c09766a3-d157-472b-b9ee-8a3d1bf2b107", "type": "concept", "title": "Mediterranean"}, {"id": "21bd2566-b381-4372-a30c-51ab2b82456e", "type": "concept", "title": "Near East"}], "description": "Students learn the basic spatial and chronological frame needed for everything else in the course."}, {"id": "97a2e9f6-b65a-4482-bd06-83ac0361e4ea", "type": "subtopic", "title": "Ancient evidence and its limits", "children": [{"id": "cfff1eae-84a8-462d-99c9-f69630454f57", "type": "concept", "title": "textual sources"}, {"id": "df593d0d-2143-41b0-8ccd-454f38c4c735", "type": "concept", "title": "inscriptions"}, {"id": "d9289f80-ffeb-4842-a5e6-7809061f247c", "type": "concept", "title": "papyri"}, {"id": "200442c6-e7af-412c-9aa9-1d2a81142b9e", "type": "concept", "title": "coins"}, {"id": "5f09c4b7-79f5-473f-925b-81d431820ed1", "type": "concept", "title": "archaeology"}, {"id": "67654038-f8ab-466d-a796-f4c5f9c2f5a4", "type": "concept", "title": "material culture"}, {"id": "d5167140-685f-4730-a486-66148b1bfd71", "type": "concept", "title": "oral tradition"}, {"id": "79528250-a681-485c-a8dd-da63cb858385", "type": "concept", "title": "preservation bias"}, {"id": "b3add4fe-6f4b-4080-b0d1-43fbbf2d0d90", "type": "concept", "title": "elite bias"}], "description": "The point is to learn why ancient history is powerful but incomplete, and how historians reason from gaps."}, {"id": "dce9a668-345e-400a-951f-a26ecb754a7c", "type": "subtopic", "title": "Historical argument and method", "children": [{"id": "bd9af479-b7cf-417f-a9af-5e64ef229684", "type": "concept", "title": "source criticism"}, {"id": "0be8910f-eeff-475a-99f5-3148674d0698", "type": "concept", "title": "contextualization"}, {"id": "127efc2e-6a70-4be8-9f8f-3f3ac1440cff", "type": "concept", "title": "corroboration"}, {"id": "38599b80-c010-468e-8512-7a25d6d3c801", "type": "concept", "title": "chronology"}, {"id": "2e2f0af7-dab0-4ce0-bf9d-a8c64d7bd999", "type": "concept", "title": "historiography"}, {"id": "a751fb83-d579-4dfc-926f-87ac89be15e0", "type": "concept", "title": "Chicago footnotes"}, {"id": "3a78296b-2b6f-4cca-87b0-34db15d3e0d5", "type": "concept", "title": "primary source analysis"}, {"id": "82aa14a8-7d0b-4075-8dcd-4eb51620959b", "type": "concept", "title": "argument thesis"}], "description": "Students practice turning evidence into careful claims rather than simple narrative summary."}]}, {"id": "69662a3d-5b01-45ac-865a-1d1c46ccc135", "type": "topic", "title": "Origins of Cities, States, Writing, and Urban Society", "description": "This unit examines the emergence of complex societies and the tools that made states, law, administration, and social hierarchy possible. Students connect agriculture, urbanization, bureaucracy, writing, and power.", "children": [{"id": "7cd009a7-8ac5-4437-9b21-5fbce368e108", "type": "subtopic", "title": "Agriculture and settlement", "children": [{"id": "1b9ba4eb-d15a-4235-8b08-89683565bc2a", "type": "concept", "title": "domestication"}, {"id": "01756a2f-be60-4f81-a6e2-6e86dd23e407", "type": "concept", "title": "surplus"}, {"id": "485709a1-b7cd-407d-9f10-52fe9a1028eb", "type": "concept", "title": "irrigation"}, {"id": "9d20e8e5-5f51-4aa3-ad2a-4e4385c6504b", "type": "concept", "title": "sedentism"}, {"id": "8f728add-75cb-4658-a860-7fd760095ab5", "type": "concept", "title": "village life"}, {"id": "189ab4b2-df2d-47e8-ab8d-77e9dafada6f", "type": "concept", "title": "labor specialization"}, {"id": "cdef44fe-81a8-4070-93a0-d1c514d015fc", "type": "concept", "title": "population growth"}, {"id": "911b05c8-ef22-4b18-b944-cb5937f84601", "type": "concept", "title": "environmental stress"}], "description": "Students study how food production reshaped demography, labor, environment, and social organization."}, {"id": "6c02a704-5bc1-42ec-adc5-7ecf89638c65", "type": "subtopic", "title": "Cities and institutions", "children": [{"id": "0bbd4cf9-af21-4bc1-a55d-9ca8df03129c", "type": "concept", "title": "urbanism"}, {"id": "578aebeb-2bd3-4d7f-8e41-74fb35f87580", "type": "concept", "title": "temple economy"}, {"id": "581a633f-ee2c-4aa1-bb33-e8589b20c352", "type": "concept", "title": "palace economy"}, {"id": "21467161-8267-427c-8b63-7da48dce7d62", "type": "concept", "title": "bureaucracy"}, {"id": "9cbfbdd5-7112-467b-b797-eddd67c5ae48", "type": "concept", "title": "taxation"}, {"id": "78e65af6-1b27-4a91-a5ce-22b2ab867480", "type": "concept", "title": "law codes"}, {"id": "a8e57d94-688d-4c4c-914b-5ce4274c412a", "type": "concept", "title": "social stratification"}, {"id": "9e57ef53-c8a5-462c-90b6-d9f7e82730be", "type": "concept", "title": "craft production"}], "description": "This subtopic shows how urban centers became sites of administration, religion, trade, and inequality."}, {"id": "17f7326f-fdd6-42eb-89bb-0030f9d0ab86", "type": "subtopic", "title": "Writing and record keeping", "children": [{"id": "d823c637-e5ae-410c-8675-9b19ee2dcc4f", "type": "concept", "title": "cuneiform"}, {"id": "75e55e90-1645-40a9-9fde-3817c3ce5ed0", "type": "concept", "title": "hieroglyphs"}, {"id": "7b4afeaf-ad5a-41e0-9fa2-eeb2120606b0", "type": "concept", "title": "scribes"}, {"id": "7360a31c-a723-4e75-98b7-9d8d5ddb4703", "type": "concept", "title": "archives"}, {"id": "69f4d026-7fa3-461f-a4b8-aed150835931", "type": "concept", "title": "accounting tablets"}, {"id": "aa7b88b8-f0b5-4b96-9a26-0e0b4ed579e7", "type": "concept", "title": "legal contracts"}, {"id": "1bd161f2-b97a-4c68-8ffe-adfb78ccfb2a", "type": "concept", "title": "royal inscriptions"}, {"id": "a556f7cf-e0b1-4a07-b279-a2844cc298d0", "type": "concept", "title": "literacy"}], "description": "Students learn why writing systems changed government, memory, commerce, and historical visibility."}]}, {"id": "7ef3e171-118c-4ac3-9b3c-1215eb77fc1c", "type": "topic", "title": "Ancient Mesopotamia: City-States, Law, and Empire", "description": "Mesopotamia introduces students to early urban states, literary traditions, law, imperial administration, and the politics of river-valley civilization. Students learn how Sumerian, Akkadian, Babylonian, and Assyrian developments shaped ancient Near Eastern history.", "children": [{"id": "e1bf0bdc-86b3-40fa-b343-d1666a9fb064", "type": "subtopic", "title": "Sumer and early city-states", "children": [{"id": "40925017-40c8-41af-992d-b93289acae0c", "type": "concept", "title": "Uruk"}, {"id": "459a35f1-2f37-440e-a448-7c1ec7fbe438", "type": "concept", "title": "Ur"}, {"id": "9b5e1cb2-8e39-412a-adbc-1d811509ca77", "type": "concept", "title": "Lagash"}, {"id": "b0e7f886-25db-4be1-86a0-d5ea83da126c", "type": "concept", "title": "city-state"}, {"id": "addae0d9-f829-4f23-9d36-7885e6028826", "type": "concept", "title": "ziggurat"}, {"id": "4ab90a7c-231a-4cb6-a82c-c6cc2f232bed", "type": "concept", "title": "ensi"}, {"id": "42ebca62-b7cc-4aba-a3da-0c9203cb3371", "type": "concept", "title": "temple household"}, {"id": "a44fd15d-07a9-4c22-9ea4-adf8e3752cae", "type": "concept", "title": "Gilgamesh"}, {"id": "191888b6-ce0e-4583-a82b-42ceec9e909b", "type": "concept", "title": "cylinder seals"}], "description": "The goal is to understand local political forms before territorial empire."}, {"id": "6de5a0d5-a730-4aae-9681-67e437f244b5", "type": "subtopic", "title": "Law, kingship, and social order", "children": [{"id": "f735182c-9bea-4e1c-aa6f-b8a1cb6edf41", "type": "concept", "title": "Code of Hammurabi"}, {"id": "54dec066-4cd2-4cdf-bb8d-56aa97bd3bbc", "type": "concept", "title": "lex talionis"}, {"id": "67a69f32-e6b0-47b8-9e65-99cb7314f6c0", "type": "concept", "title": "status groups"}, {"id": "9bb1f750-b540-4097-a8eb-1a11e7e602ca", "type": "concept", "title": "debt"}, {"id": "fc492bb6-bc48-4a48-a80a-a5016455638a", "type": "concept", "title": "slavery"}, {"id": "2c77ea18-0093-4924-a92c-4d2c379b2a96", "type": "concept", "title": "patriarchy"}, {"id": "4cdd5df5-a98e-4738-8cac-bcc55e042338", "type": "concept", "title": "royal ideology"}, {"id": "720d7df1-0581-428f-a2a0-86f98bdde9e8", "type": "concept", "title": "legal pluralism"}], "description": "Students examine how rulers represented justice and how law encoded hierarchy."}, {"id": "2cda7a5d-d10a-412b-b07e-63f56e7f73c7", "type": "subtopic", "title": "Assyria and imperial power", "children": [{"id": "3d4314a3-42b4-4fe2-b6bb-4cac0a2e6662", "type": "concept", "title": "Neo-Assyrian Empire"}, {"id": "8a19e5de-6095-4c1e-beec-95a685573590", "type": "concept", "title": "Nineveh"}, {"id": "f0717b58-f8aa-4eb3-8455-c269510cc963", "type": "concept", "title": "deportation"}, {"id": "98ac3e3f-386d-40ab-a092-4fbbdb02eae4", "type": "concept", "title": "tribute"}, {"id": "44417e20-84a7-49ca-843a-876883a0a6f0", "type": "concept", "title": "military logistics"}, {"id": "420d4b88-a42b-481e-9447-427c0c2497f6", "type": "concept", "title": "provincial administration"}, {"id": "92918225-fccc-4205-bbe7-2a8a4bf884b4", "type": "concept", "title": "palace reliefs"}, {"id": "38284a79-109f-413d-8c49-93c0453c1086", "type": "concept", "title": "Ashurbanipal"}], "description": "This subtopic shows the mechanisms and costs of territorial empire."}]}, {"id": "7a7afa30-d6c3-4123-9831-a254ec0b7c02", "type": "topic", "title": "Ancient Egypt: Nile Ecology, Kingship, Religion, and Society", "description": "This topic treats Egypt as a long-lived civilization whose environment, institutions, belief systems, and monuments must be studied together. Students learn to connect ecology, ideology, material culture, and social organization.", "children": [{"id": "ec76dad5-220e-48e3-be55-e4280585dcb3", "type": "subtopic", "title": "Nile ecology and state formation", "children": [{"id": "c1488fea-7650-4f21-9a14-070091592a4d", "type": "concept", "title": "inundation"}, {"id": "5d9cfa91-2aa1-42e3-a7ab-cdf1623bd1e8", "type": "concept", "title": "floodplain agriculture"}, {"id": "4c94eab3-002e-42c4-9b8a-4f470529bf88", "type": "concept", "title": "Upper Egypt"}, {"id": "51e086bf-3a2f-46e6-af80-60dedc8133cd", "type": "concept", "title": "Lower Egypt"}, {"id": "9e00963a-8d32-4012-823b-a1e3aa5c9093", "type": "concept", "title": "Memphis"}, {"id": "bd1ed3a2-8261-4026-82c9-9015fe2ce5aa", "type": "concept", "title": "nome"}, {"id": "1afef5a1-af2b-4a71-9188-38e55b631e85", "type": "concept", "title": "granaries"}, {"id": "bbcd259a-9577-43fc-81e8-724c7e90f7f0", "type": "concept", "title": "centralization"}], "description": "Students learn how the Nile shaped agriculture, transport, taxation, and political integration."}, {"id": "33aee246-4874-4d15-8fef-8d98c8355db3", "type": "subtopic", "title": "Pharaoh, gods, and cosmic order", "children": [{"id": "07554acd-2a15-4404-ad12-f548cc1b6326", "type": "concept", "title": "pharaoh"}, {"id": "516bd966-3a7b-4589-bce7-6d02f461c928", "type": "concept", "title": "ma'at"}, {"id": "d8878ad3-2894-4b6d-a1a6-f2a738942fc6", "type": "concept", "title": "Osiris"}, {"id": "a4d7fb9e-fe7c-4bea-955a-0b61a009831d", "type": "concept", "title": "Isis"}, {"id": "0caea65b-f8be-4ead-8a30-80832c4793c9", "type": "concept", "title": "Ra"}, {"id": "a0b5b53d-d36e-46b6-8e67-819ac365f713", "type": "concept", "title": "Amun"}, {"id": "9a699c1b-6278-458d-89ed-899894ebc218", "type": "concept", "title": "divine kingship"}, {"id": "21d193fe-6c13-45bf-bf29-f0fd7327fe5d", "type": "concept", "title": "temple ritual"}, {"id": "e65492c6-bb41-4a66-871e-8a1387a5c42a", "type": "concept", "title": "afterlife"}], "description": "This subtopic explains kingship as political, religious, and symbolic power."}, {"id": "cc59c4e5-0548-41f4-a9ce-c27a0da13f9d", "type": "subtopic", "title": "Monuments, labor, and daily life", "children": [{"id": "f63b5cd4-65ae-4e22-8eac-59f82c840340", "type": "concept", "title": "pyramids"}, {"id": "d5e8145a-7f54-44c7-8e10-1572e681e64c", "type": "concept", "title": "mastaba"}, {"id": "5ecb0a95-5865-4032-8ae3-132db0258a62", "type": "concept", "title": "tomb painting"}, {"id": "a72c3eb8-51f7-4f67-ae07-1e96653a382e", "type": "concept", "title": "Deir el-Medina"}, {"id": "9931672c-8a14-4c8f-a9f8-50533c196382", "type": "concept", "title": "corvee labor"}, {"id": "e331f946-ab43-4aeb-a555-84b4a66de4ba", "type": "concept", "title": "scribal culture"}, {"id": "642ec170-c0c2-4cc8-bc0e-42b52e230d17", "type": "concept", "title": "households"}, {"id": "cf948778-b567-420e-8cfa-955cae4d94d1", "type": "concept", "title": "gender roles"}], "description": "Students read monuments as social evidence, not just spectacle."}]}, {"id": "2a3188db-118d-4106-a071-829160cde0de", "type": "topic", "title": "Bronze Age Networks, Collapse, and the Eastern Mediterranean", "description": "This unit examines the interconnected Bronze Age world and the causes and consequences of its disruption around 1200 BCE. Students analyze trade, diplomacy, warfare, climate, migration, and systems collapse.", "children": [{"id": "5ca8d2dc-e6d1-461a-8389-998f33be5e82", "type": "subtopic", "title": "Diplomacy and exchange", "children": [{"id": "c67b9c75-70a0-4d0a-b5a3-79c438c3edbc", "type": "concept", "title": "Amarna letters"}, {"id": "34c98653-81ae-403b-bcb4-1b63dac6cd45", "type": "concept", "title": "diplomatic marriage"}, {"id": "09fa580f-ab05-4ad5-b945-ec640ee9b4ec", "type": "concept", "title": "gift exchange"}, {"id": "85251a4b-4c96-44be-9542-9dde30efdb89", "type": "concept", "title": "tin trade"}, {"id": "9a95660e-3303-4e58-a1aa-f9a388216992", "type": "concept", "title": "copper"}, {"id": "5160ac7a-0605-4886-88a7-87049ff4ea72", "type": "concept", "title": "Ugarit"}, {"id": "f424812f-bc38-4ec5-9720-98cd1159fd58", "type": "concept", "title": "Cyprus"}, {"id": "644c07ab-804d-40a7-8328-075a04cf50b6", "type": "concept", "title": "palatial economies"}], "description": "Students learn that Bronze Age polities were connected through gifts, marriage, trade, and correspondence."}, {"id": "9bd00be8-b047-4c2e-accd-9e6530e3c19e", "type": "subtopic", "title": "Anatolia, the Levant, and Aegean worlds", "children": [{"id": "b52dfbe9-e6fa-489b-a913-7989c7a89bb3", "type": "concept", "title": "Hittites"}, {"id": "f0c9bac4-1aac-4ad0-ba19-e77cd6498c29", "type": "concept", "title": "Mycenaeans"}, {"id": "6479b401-34c0-435c-90b5-c94860fcfe74", "type": "concept", "title": "Minoans"}, {"id": "919e2af7-c276-4963-9478-04c26745d2c4", "type": "concept", "title": "Knossos"}, {"id": "cb75092c-6f09-48cf-b6ea-66cc5b797bc8", "type": "concept", "title": "Hattusa"}, {"id": "96a2c03f-249a-4538-a31a-3d6b513dc2cb", "type": "concept", "title": "Levantine ports"}, {"id": "136c27c2-46a2-446a-980a-b6b2a19c5b87", "type": "concept", "title": "Linear B"}, {"id": "c1e4ef50-bae3-41eb-8a9e-ef1ed56074af", "type": "concept", "title": "chariot warfare"}], "description": "This subtopic broadens the field beyond Egypt and Mesopotamia."}, {"id": "7a82fe27-1992-429d-b00f-01ee3f4a49de", "type": "subtopic", "title": "Bronze Age collapse", "children": [{"id": "19841f78-359e-47cf-a869-c95fe6c32de8", "type": "concept", "title": "Sea Peoples"}, {"id": "a8701076-c2c9-4c51-bb71-c9be7e91e5e2", "type": "concept", "title": "climate stress"}, {"id": "e8768150-0f31-4b22-99f1-2b8ce50076c2", "type": "concept", "title": "earthquakes"}, {"id": "de083ecb-f80b-4485-9ebe-066b0deecbcd", "type": "concept", "title": "systems collapse"}, {"id": "ac6fef81-6d41-42a4-bdc4-cb35c1a3de30", "type": "concept", "title": "migration"}, {"id": "8d1d48fc-4753-451b-a7ab-18493ed42c34", "type": "concept", "title": "trade disruption"}, {"id": "96d523f2-f703-4238-9a54-2416757dfc7a", "type": "concept", "title": "palace destruction"}, {"id": "99d5d225-2850-4378-84b8-69bc81ecf8e2", "type": "concept", "title": "continuity and transformation"}], "description": "Students compare mono-causal and multi-causal explanations for historical breakdown."}]}, {"id": "1e549a39-1e1a-4a2d-8a2b-cd0d65452bfd", "type": "topic", "title": "Iron Age States, Israel, Phoenicia, and the Achaemenid Persian Empire", "description": "This topic follows new political and cultural formations after the Bronze Age and culminates in the first major empire spanning much of the Near East. Students learn how smaller kingdoms, maritime networks, and imperial systems remade the ancient world.", "children": [{"id": "a3ee796d-398e-4a2d-9317-046f947fd78e", "type": "subtopic", "title": "Iron Age kingdoms and identities", "children": [{"id": "1f6d885e-00db-47cc-85a5-8a78e6438032", "type": "concept", "title": "Israel"}, {"id": "5c769d2d-5fa1-41fc-9e81-462b5f4910c7", "type": "concept", "title": "Judah"}, {"id": "e04d1554-8549-41ae-a8d3-0c586a5eb960", "type": "concept", "title": "Moab"}, {"id": "b90e08e7-842d-4430-b5dc-a953bc82b426", "type": "concept", "title": "Aram"}, {"id": "7db670c9-6593-4f13-80b1-5ef87de63fe6", "type": "concept", "title": "Hebrew Bible as source"}, {"id": "aa306308-1800-46b6-bc27-d4cf89a60171", "type": "concept", "title": "monarchy"}, {"id": "44d935b4-d2e7-42bf-87ee-a5745c2dd84c", "type": "concept", "title": "exile"}, {"id": "8f02979c-498c-479e-865e-258a5f38c048", "type": "concept", "title": "ethnogenesis"}], "description": "Students study how communities used texts, kingship, and memory to define collective identity."}, {"id": "7f34ce70-a683-4148-a93c-0992b84c9bf7", "type": "subtopic", "title": "Phoenicians and Mediterranean connectivity", "children": [{"id": "b6a81f0c-cba3-4b43-ba94-14304596e76c", "type": "concept", "title": "Tyre"}, {"id": "7a0ce985-b49e-434b-8a53-32604f97a521", "type": "concept", "title": "Sidon"}, {"id": "1d82b93c-1ae2-4aae-88b5-f91510c324cb", "type": "concept", "title": "Carthage"}, {"id": "ff4c8c60-1964-48d1-aa53-a6f9698038e5", "type": "concept", "title": "alphabet"}, {"id": "564f93fe-f8ec-41e7-947b-4f295ea5088d", "type": "concept", "title": "maritime trade"}, {"id": "bfe92a61-b73f-427a-a444-b48dd8ed39b6", "type": "concept", "title": "colonies"}, {"id": "8897b465-6e24-404c-be85-71471289d30b", "type": "concept", "title": "purple dye"}, {"id": "28d49806-3207-4c14-a5f0-e15e9aac7df6", "type": "concept", "title": "Mediterranean networks"}], "description": "This subtopic shows how trade and colonization linked regions before Greek and Roman dominance."}, {"id": "222565d2-be2b-421c-b8e4-554cb41749e8", "type": "subtopic", "title": "Achaemenid Persia", "children": [{"id": "8e974b52-36e4-4a93-b980-976dcb5220f5", "type": "concept", "title": "Cyrus"}, {"id": "db03f145-c350-4712-ae0f-74eaaa9554b9", "type": "concept", "title": "Darius"}, {"id": "4271a2b1-0870-4e0a-a853-105816de7d4d", "type": "concept", "title": "satrapy"}, {"id": 