le": "Colonization and mobility", "children": [{"id": "d34f646e-b5c6-46cb-b98e-fd9300c8ffc8", "type": "concept", "title": "apoikia"}, {"id": "eb1f19f9-6c0a-49c1-ab16-339a5a03fc24", "type": "concept", "title": "metropole"}, {"id": "1ea86ef4-7c9f-4640-a926-90ac6722d8ae", "type": "concept", "title": "Magna Graecia"}, {"id": "a1032394-1dcc-419f-a922-beb861105eda", "type": "concept", "title": "Black Sea colonies"}, {"id": "fda247dc-b03e-4c15-8a58-504d9d525a4a", "type": "concept", "title": "trade"}, {"id": "61cb1a30-08cc-448e-a1eb-e83bf1337202", "type": "concept", "title": "land hunger"}, {"id": "c8a98c57-dded-4248-a69c-24abc327409b", "type": "concept", "title": "cultural exchange"}, {"id": "9a7c19f2-f7f9-4a84-8ef6-e5f583e9b33b", "type": "concept", "title": "colonial violence"}], "description": "This subtopic looks at Greek settlements as economic, demographic, and cultural expansion."}, {"id": "a4ab32f4-ea89-406c-a540-7f6fc7400892", "type": "subtopic", "title": "Lawgivers, tyrants, and social reform", "children": [{"id": "db3534d6-11b1-467f-b401-e522fde79ae1", "type": "concept", "title": "Draco"}, {"id": "4cd79993-8812-466c-9dac-85dfe82a39b2", "type": "concept", "title": "Solon"}, {"id": "45c11e8d-6990-4a21-88f9-599346384004", "type": "concept", "title": "tyranny"}, {"id": "4fdc35dc-fe6f-49af-9bdf-5fce52b16524", "type": "concept", "title": "stasis"}, {"id": "f9f4b02f-3513-4bb2-83c2-d41fdf622ecd", "type": "concept", "title": "debt bondage"}, {"id": "05382cb4-869e-4bda-bb3b-2f13f351d15a", "type": "concept", "title": "aristocracy"}, {"id": "e004056a-2bcc-45c5-9d39-2d8efb67ea52", "type": "concept", "title": "symposium"}, {"id": "802dd82c-e95d-4469-a31f-05dd99f42ed4", "type": "concept", "title": "written law"}], "description": "Students connect political change to debt, aristocracy, and popular pressure."}]}, {"id": "20ca5178-6920-4c44-b4d6-b1a7f83b4edc", "type": "topic", "title": "Classical Greece: Democracy, Empire, War, and Culture", "description": "This topic examines the Classical Greek world through Athens, Sparta, Persian conflict, imperial power, and cultural production. Students analyze democracy, militarization, empire, drama, philosophy, and historical writing together.", "children": [{"id": "29b40d34-1c59-4431-a5aa-d818260e7fcb", "type": "subtopic", "title": "Athens and democracy", "children": [{"id": "38e7e0c7-e77f-4563-8933-30b3ba1345c0", "type": "concept", "title": "ekklesia"}, {"id": "7c9abc93-1555-48d2-9ab3-67b7597d88f5", "type": "concept", "title": "boule"}, {"id": "3dcb94f5-cf55-4293-9c56-acae25fc2bed", "type": "concept", "title": "dikasteria"}, {"id": "8104fd40-1558-47f2-828b-c3aab9b8def8", "type": "concept", "title": "ostracism"}, {"id": "bb894fe3-9273-4724-b395-87b3f342b3be", "type": "concept", "title": "liturgies"}, {"id": "90040217-c834-45e8-b481-966414b11a66", "type": "concept", "title": "metoikoi"}, {"id": "33412643-f2d1-45c3-8d47-1b8f94df8f84", "type": "concept", "title": "slavery"}, {"id": "452b525d-bcbf-465d-9075-f5b7c4efa15c", "type": "concept", "title": "Pericles"}], "description": "Students learn the institutions and exclusions of direct democracy."}, {"id": "0d34cff7-ebe5-4002-9faf-b1d5e54918bc", "type": "subtopic", "title": "Sparta, Persia, and war", "children": [{"id": "6b2a94ac-f627-46dc-98c8-7e5660fb7854", "type": "concept", "title": "Sparta"}, {"id": "c0113e76-d739-4b2f-ae07-60822a325f07", "type": "concept", "title": "helots"}, {"id": "b229b4cc-ec42-4462-9603-b0cf557f37bb", "type": "concept", "title": "agoge"}, {"id": "ead34dd9-89c5-4292-8e1a-b96d013951ef", "type": "concept", "title": "Persian Wars"}, {"id": "04e4915d-b79c-4c54-bba6-3b56f6e99ec0", "type": "concept", "title": "Marathon"}, {"id": "54f16c61-88b9-48ea-be0a-278f69b17255", "type": "concept", "title": "Thermopylae"}, {"id": "489512bf-8103-41e3-8eef-23d848d38578", "type": "concept", "title": "Delian League"}, {"id": "8c7e90d1-cda6-4a3c-a0fb-23194841a7dc", "type": "concept", "title": "Peloponnesian War"}], "description": "This subtopic compa